namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}}
bool ScriptSession::cloudTarget(const UnitState& target,const SpellInfo& s){
    if(!target.structureTarget || target.removing || target.hidden() || target.swarmAgent || number(target.life)<=0 || capability(target,"Amim") || capability(target,"Aloc"))return false;bool invulnerable=target.invulnerable || capability(target,"Avul");return s.allowed.contains("structure") && (!invulnerable || s.allowed.contains("invu") || s.allowed.contains("invulnerable"));
}
void ScriptSession::aggregateCloud(UnitBuff& buff){buff.disableMask=0;buff.missChance=buff.moveReduction=buff.attackReduction=0;for(auto& [source,lease]:buff.suppressionSources){buff.disableMask|=lease.disableMask;buff.missChance=std::max(buff.missChance,lease.missChance);buff.moveReduction=std::max(buff.moveReduction,lease.moveReduction);buff.attackReduction=std::max(buff.attackReduction,lease.attackReduction);}}
void ScriptSession::releaseHumanClaim(std::uint32_t source,std::uint64_t ticket,std::uint32_t id,std::uint32_t buff){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);auto found=u->buffs.find(buff);if(found==u->buffs.end())return;auto& b=found->second;if(b.kind==BuffKind::Cloud){auto lease=b.suppressionSources.find(source);if(lease==b.suppressionSources.end() || lease->second.ticket!=ticket)return;b.suppressionSources.erase(lease);if(!b.suppressionSources.empty()){aggregateCloud(b);return;}}else if(b.kind==BuffKind::ShacklesTarget){auto lease=b.channelSources.find(source);if(lease==b.channelSources.end() || lease->second!=ticket)return;b.channelSources.erase(lease);if(!b.channelSources.empty())return;}else if(b.kind!=BuffKind::ShacklesCaster || b.source!=source || b.applied!=ticket)return;releaseBuff(b);u->buffs.erase(found);
}
void ScriptSession::releaseHumanChannel(const CastOrder& cast){if(cast.spell.kind!=SpellKind::Cloud && cast.spell.kind!=SpellKind::AerialShackles)return;for(auto [id,buff]:cast.suppressionMarks)releaseHumanClaim(cast.caster,cast.ticket,id,buff);for(auto id:cast.lightnings)destroyLightning(id);}
void ScriptSession::startHumanChannel(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!u->cast || u->cast->ticket!=cast.ticket)return;auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->cast && u->cast->ticket==cast.ticket && u->owner==cast.owner;};if(cast.spell.kind==SpellKind::Cloud){startChannel(id);if(active()){auto channel=*u->cast;cloudPulse(id,channel);}return;}if(!alive(cast.target,NativeKind::Unit))return;auto target=units_.at(cast.target);if(!spellTarget(*u,*target,cast.spell,false,cast.owner)){cancelCast(*u);return;}u->cast->spell.channelTime=target->hero || capability(*target,"Arsk")?cast.spell.heroDuration:cast.spell.duration;if(u->cast->spell.channelTime<=0){cancelCast(*u);return;}startChannel(id);if(!active())return;auto definition=u->cast->spell;applyBuff(id,id,definition,BuffKind::ShacklesCaster,true);if(auto b=u->buffs.find(definition.buff);b!=u->buffs.end() && b->second.kind==BuffKind::ShacklesCaster){b->second.persistent=true;b->second.positive=true;b->second.dispellable=false;b->second.applied=cast.ticket;u->cast->suppressionMarks.emplace_back(id,definition.buff);}definition.buff=definition.guardBuff;auto found=target->buffs.find(definition.buff);if(found==target->buffs.end() || found->second.kind!=BuffKind::ShacklesTarget){applyBuff(cast.target,id,definition,BuffKind::ShacklesTarget);found=target->buffs.find(definition.buff);}if(found==target->buffs.end() || found->second.kind!=BuffKind::ShacklesTarget){cancelCast(*u);return;}found->second.persistent=true;found->second.channelSources[id]=cast.ticket;found->second.originAbility=definition.ability;found->second.sourceLevel=definition.level;u->cast->suppressionMarks.emplace_back(cast.target,definition.buff);target->route.clear();target->waypoint=0;target->currentOrder=0;cancelCombat(*target);if(active()){if(!alive(cast.target,NativeKind::Unit) || target->removing || number(target->life)<=0){cancelCast(*u);return;}auto type=definitions().field(cast.spell.ability,"Profile","LightningEffect");if(auto comma=type.find(',');comma!=std::string::npos)type.resize(comma);if(type.size()!=4)throw std::runtime_error("Aerial Shackles requires its source lightning type");float from=definitions().number(u->type,"UnitWeapons","launchZ"),to=definitions().number(target->type,"UnitWeapons","impactZ",60);auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};auto lightning=createLightning(type,true,{u->x,u->y,real(requireWorld().height({u->x,u->y})+u->displayFlyHeight()+from)},{target->x,target->y,real(requireWorld().height({target->x,target->y})+target->displayFlyHeight()+to)},{});auto state=lightnings_.at(lightning.bits);state->fromUnit=id;state->toUnit=cast.target;state->fromHeight=from;state->toHeight=to;u->cast->lightnings.push_back(lightning.bits);}
}
void ScriptSession::cloudPulse(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->cast && u->cast->ticket==cast.ticket && u->owner==cast.owner;};if(!active())return;auto& s=cast.spell;auto old=u->cast->suppressionMarks;std::vector<std::uint32_t> targets;for(auto& [target,unit]:units_)if(unit->structureTarget && cloudTarget(*unit,s) && std::hypot(number(unit->x)-number(cast.point.x),number(unit->y)-number(cast.point.y))<=s.area+unit->collision)targets.push_back(target);std::vector<std::pair<std::uint32_t,std::uint32_t>> marks;
    for(auto target:targets){if(!active())return;if(!alive(target,NativeKind::Unit))continue;auto unit=units_.at(target);if(!cloudTarget(*unit,s))continue;auto found=unit->buffs.find(s.buff);if(found==unit->buffs.end() || found->second.kind!=BuffKind::Cloud){auto definition=s;definition.duration=definition.heroDuration=std::max(.125f,s.period*2);applyBuff(target,id,definition,BuffKind::Cloud);found=unit->buffs.find(s.buff);}if(found==unit->buffs.end() || found->second.kind!=BuffKind::Cloud)continue;auto& b=found->second;b.persistent=true;b.positive=false;b.suppressionSources[id]={cast.ticket,s.disableMask,s.missChance,s.moveReduction,s.attackReduction};aggregateCloud(b);auto mark=std::pair{target,s.buff};marks.push_back(mark);if(std::find(u->cast->suppressionMarks.begin(),u->cast->suppressionMarks.end(),mark)==u->cast->suppressionMarks.end())u->cast->suppressionMarks.push_back(mark);if((b.disableMask&8) && unit->cast && !unit->cast->item)cancelCast(*unit);}
    if(!active())return;for(auto [target,buff]:old)if(std::find(marks.begin(),marks.end(),std::pair{target,buff})==marks.end())releaseHumanClaim(id,cast.ticket,target,buff);if(active())u->cast->suppressionMarks=std::move(marks);
}
bool ScriptSession::humanChannelTick(std::uint32_t id,double delta){
    auto u=units_.at(id);if(!u->cast)return true;auto kind=u->cast->spell.kind;if(kind!=SpellKind::Cloud && kind!=SpellKind::AerialShackles)return false;auto ticket=u->cast->ticket;auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->cast && u->cast->ticket==ticket && u->owner==u->cast->owner;};auto cast=*u->cast;auto& s=cast.spell;if(kind==SpellKind::Cloud){if(std::hypot(number(u->x)-number(cast.point.x),number(u->y)-number(cast.point.y))>s.range+u->collision){cancelCast(*u);return true;}return false;}if(!alive(cast.target,NativeKind::Unit)){cancelCast(*u);return true;}auto target=units_.at(cast.target);auto claim=target->buffs.find(s.guardBuff);bool linked=claim!=target->buffs.end() && claim->second.kind==BuffKind::ShacklesTarget && claim->second.channelSources.contains(id) && claim->second.channelSources.at(id)==ticket;auto mark=u->buffs.find(s.buff);if(!linked || mark==u->buffs.end() || mark->second.kind!=BuffKind::ShacklesCaster || mark->second.applied!=ticket || !spellTarget(*u,*target,s,false,cast.owner) || std::hypot(number(u->x)-number(target->x),number(u->y)-number(target->y))>s.range+u->collision+target->collision){cancelCast(*u);return true;}auto death=target->deathRevision;u->cast->channelElapsed=std::min(u->cast->channelElapsed+delta,double(s.channelTime));while(active() && u->cast->nextPulse<=u->cast->channelElapsed+1e-7){u->cast->nextPulse+=s.period;++u->cast->pulses;damageUnit(id,cast.target,s.amount*s.period,0,14);if(!active())break;if(!alive(cast.target,NativeKind::Unit) || target->removing || number(target->life)<=0 || target->deathRevision!=death){cancelCast(*u);break;}}if(active() && u->cast->channelElapsed>=s.channelTime)finishCast(id,ticket);return true;
}
